    const glob = await addInventoryObject(GLOB_OF_GRAY_OOZE, { owt: 1 });
    stopAllObjectTimers(glob);
    scheduleObjectTimer(glob, OBJECT_TIMER_KIND.SHRINK_GLOB, game.moves);
    game._encumbranceLevel = nearCapacity(game);
    assert.equal(game._encumbranceLevel, 1);
    const timer = claimNextDueObjectTimer(game, game.moves);
    assert.ok(timer);
    const input = resetInputState();
    const messages = [];
    input.beforeRead = () => { messages.push(game._pending_message); input.feed(' '); };
    await runObjectTimer(timer, game.moves);
    await reportHeroEncumbrance();
    messages.push(game._pending_message);
    assert.equal(glob.where, 'gone');
    assert.equal(messages.filter(message => message.includes('now unencumbered')).length, 1, `Load messages: ${messages.join(' | ')}`);
